mapper.select:
SELECT  FROM ocean_gis.gis_vector_layer l
JOIN ocean_gis.gis_data_set ds ON ds.id = l.data_set_id AND ds.deleted = 0
WHERE l.deleted = 0 AND l.layer_status = 'READY' AND l.group_id IS NOT NULL
AND l.data_set_id = #{dataSetId}
AND l.group_id = #{groupId}
AND l.source_file_id = #{sourceFileId}
ORDER BY l.id DESC

SELECT v.feature_index, ST_IsValidReason(v.geom) AS reason FROM (VALUES
(#{f.sourceFeatureIndex,jdbcType=BIGINT}, ST_GeomFromGeoJSON(#{f.geometryJson}))
) v(feature_index, geom) WHERE NOT ST_IsValid(v.geom) LIMIT 1

WITH candidates AS (
SELECT f.id,f.layer_id,NULL::text AS geometry_json,f.properties::text AS properties_json,
    f.version,f.source_feature_id::text AS source_feature_id,f.source_feature_index,f.source_geometry_path,f.classification_rule_key
FROM ocean_gis.gis_vector_feature f
WHERE f.layer_id = #{layerId} AND f.deleted = 0 AND f.id > #{afterId}



            AND ST_Intersects(f.geom, ST_MakeEnvelope(#{west},#{south},#{east},#{north},4326))


            AND (ST_Intersects(f.geom, ST_MakeEnvelope(#{west},#{south},180,#{north},4326))
             OR ST_Intersects(f.geom, ST_MakeEnvelope(-180,#{south},#{east},#{north},4326)))



ORDER BY f.id LIMIT #{limit}
), sized AS (
    SELECT *, COALESCE(octet_length(geometry_json),0) + COALESCE(octet_length(properties_json),4) + 256 AS row_bytes
    FROM candidates
), bounded AS (
    SELECT *, sum(row_bytes) OVER (ORDER BY id ROWS UNBOUNDED PRECEDING) AS total_bytes FROM sized
)
SELECT * FROM bounded WHERE total_bytes - row_bytes < 8388608 ORDER BY id

mapper.update:
UPDATE ocean_gis.gis_vector_style SET name = #{s.name}, definition = CAST(#{s.definitionJson} AS jsonb),
    version = version + 1, update_time = CURRENT_TIMESTAMP
WHERE id = #{s.id} AND layer_id = #{s.layerId} AND version = #{expected}

mapper.select:
SELECT  FROM ocean_gis.gis_vector_dataset_style s
JOIN ocean_gis.gis_data_set ds ON ds.id=s.data_set_id AND ds.deleted=0 AND ds.category_id=2
WHERE s.data_set_id=#{dataSetId}

SELECT  FROM ocean_gis.gis_vector_layer l
WHERE l.data_set_id=#{dataSetId} AND l.deleted=0 AND l.layer_status='READY' AND l.enabled
    AND l.style_mode!='UNCONFIGURED' AND l.group_id IN
    #{id}

    AND l.id IN #{id}

ORDER BY l.id LIMIT 1025


, members AS (
    SELECT c.id,c.layer_id,c.properties,f.version FROM cells c
    JOIN ocean_gis.gis_vector_feature f ON f.id=c.id
    WHERE c.clustered AND c.group_id=#{groupId} AND c.cell_x=#{cellX} AND c.cell_y=#{cellY}
), page AS (
    SELECT *,properties::text AS properties_json FROM members WHERE id > #{afterId} ORDER BY id LIMIT #{limit}
), sized AS (
    SELECT *,sum(COALESCE(octet_length(properties_json),4)+128) OVER(ORDER BY id) AS total_bytes,
        COALESCE(octet_length(properties_json),4)+128 AS row_bytes FROM page
)
SELECT id,layer_id,properties_json,version FROM sized WHERE total_bytes-row_bytes < 8388608 ORDER BY id
